INSERT INTO `colleges` VALUES (1,'De La Salle University - Dasmariñas','DLSU-D','Private Sectarian','dlsu-profile.html',NULL,'/riasec/assets/colleges/image1.jpeg',NULL,NULL,NULL,NULL,'De La Salle University–Dasmariñas is a Catholic Lasallian institution committed to faith, excellence, and service. It provides human and Christian education while developing competent professionals, transformative leaders, and socially responsible citizens. The university is also recognized for its strong academic programs, research, community engagement, and sustainability initiatives.','[{\"title\":\"DSAT Entrance Exam\",\"desc\":\"De La Salle University - Dasmari\\u00f1as Admission Test.\",\"status\":\"Required\"},{\"title\":\"Academic Records\\/SHS Grades\",\"desc\":\"High school report card or transcript of records.\",\"status\":\"Required\"},{\"title\":\"GPA Requirement\",\"desc\":\"Must meet the applicable GPA requirement for the desired program.\",\"status\":\"Required\"}]',0),(2,'Technological University of the Philippines','TUP','Public State U','tup-profile.html',NULL,'/riasec/assets/colleges/image2.jpeg',NULL,NULL,NULL,NULL,'Technological University of the Philippines–Cavite is a public technological university campus located in Salawag, Dasmariñas. The campus was established to address the need for technology education and skilled workers in the CALABARZON region. It offers technology-oriented programs, including three-year technology courses, bachelor\'s degrees, and master\'s programs.','[{\"title\":\"TUPSAT\",\"desc\":\"TUP Scholastic Aptitude Test.\",\"status\":\"Required\"},{\"title\":\"Online Application\",\"desc\":\"Completed online registration form from the official TUP Admission Portal.\",\"status\":\"Required\"},{\"title\":\"Form 138 (Report Card)\",\"desc\":\"Grade 12 Senior High School Card.\",\"status\":\"Required\"},{\"title\":\"PSA Birth Certificate\",\"desc\":\"Original PSA-authenticated copy.\",\"status\":\"Required\"},{\"title\":\"Good Moral Certificate\",\"desc\":\"Official Certificate of Good Moral Character.\",\"status\":\"Required\"},{\"title\":\"2x2 ID Pictures\",\"desc\":\"Recent colored photographs with formal attire.\",\"status\":\"Required\"},{\"title\":\"Long Brown Envelope\",\"desc\":\"Labeled envelope for document screening.\",\"status\":\"Required\"},{\"title\":\"Department Interview\",\"desc\":\"Interview with the respective department head.\",\"status\":\"Required\"},{\"title\":\"Medical Examination\",\"desc\":\"Health clearance from the university clinic.\",\"status\":\"Required\"}]',0),(3,'Cavite State University','CvSU','Public State U','cvsu-profile.html',NULL,'/riasec/assets/colleges/image3.png',NULL,NULL,NULL,NULL,'Cavite State University (CvSU) is a public university in Cavite dedicated to providing accessible higher education, research, extension services, and community development. Its Dasmariñas Learning Center serves students in the Dasmariñas area and contributes to CvSU\'s goal of making quality education accessible to local communities.','[{\"title\":\"Entrance Exam\",\"desc\":\"Required admission test for incoming students.\",\"status\":\"Required\"},{\"title\":\"Grade 12 Report Card\",\"desc\":\"Form 138 \\/ SF9 showing general weighted average.\",\"status\":\"Required\"},{\"title\":\"Good Moral Certificate\",\"desc\":\"Issued by the high school principal or guidance counselor.\",\"status\":\"Required\"},{\"title\":\"1x1 Pictures\",\"desc\":\"Recent colored ID pictures with white background.\",\"status\":\"Required\"},{\"title\":\"Short Folder\",\"desc\":\"For compiling all documentary requirements.\",\"status\":\"Required\"},{\"title\":\"Medical Examination\",\"desc\":\"Health clearance from the university clinic.\",\"status\":\"Required\"},{\"title\":\"Course-specific Grade\",\"desc\":\"Must meet minimum grade requirements for the chosen course.\",\"status\":\"Required\"},{\"title\":\"STEM Requirement\",\"desc\":\"Required for all Engineering programs.\",\"status\":\"Required\"}]',0),(4,'Emilio Aguinaldo College - Cavite','EAC-C','Private','eac-profile.html',NULL,'/riasec/assets/colleges/image4.jpeg',NULL,NULL,NULL,NULL,'Emilio Aguinaldo College–Cavite is a private higher education institution located in Dasmariñas. The Cavite campus was developed to expand access to education outside Metro Manila and offers programs in areas including health sciences, business, education, and other professional fields. The campus traces its development in Dasmariñas to 1977.','[{\"title\":\"Application Form\",\"desc\":\"Duly accomplished EAC admission form.\",\"status\":\"Required\"},{\"title\":\"Form 138\\/Report Card\",\"desc\":\"Grade 12 Senior High School Card.\",\"status\":\"Required\"},{\"title\":\"Good Moral Certificate\",\"desc\":\"Official certificate from previous school.\",\"status\":\"Required\"},{\"title\":\"PSA Birth Certificate\",\"desc\":\"Original PSA-authenticated copy and photocopy.\",\"status\":\"Required\"},{\"title\":\"ID Pictures\",\"desc\":\"Recent formal ID photographs.\",\"status\":\"Required\"}]',0),(5,'National College of Science and Technology','NCST','Private','ncst-profile.html',NULL,'/riasec/assets/colleges/image5.jpeg',NULL,NULL,NULL,NULL,'National College of Science and Technology (NCST) is an educational institution in Cavite focused on providing accessible education and preparing students for professional and technical careers. Its Dasmariñas campus is part of the NCST Education System and provides programs designed to develop students\' academic knowledge, technical skills, and career readiness.','[{\"title\":\"Admission Form\",\"desc\":\"Completed NCST application form.\",\"status\":\"Required\"},{\"title\":\"2x2 Pictures\",\"desc\":\"Recent colored 2x2 ID pictures.\",\"status\":\"Required\"},{\"title\":\"1x1 Pictures\",\"desc\":\"Recent colored 1x1 ID pictures.\",\"status\":\"Required\"},{\"title\":\"Form 138\\/Report Card\",\"desc\":\"Grade 12 Report Card.\",\"status\":\"Required\"},{\"title\":\"Good Moral Certificate\",\"desc\":\"Issued by the previous school.\",\"status\":\"Required\"},{\"title\":\"Long Brown Envelope\",\"desc\":\"For documentary compilation.\",\"status\":\"Required\"}]',0),(6,'Philippine Christian University','PCU','Private Sectarian','pcu-profile.html',NULL,'/riasec/assets/colleges/image6.jpeg','Sampaloc 1, Dasmariñas City, Cavite',NULL,NULL,'Philippine Christian University Dasmarinas','STI College–Dasmariñas is a private educational institution offering senior high school, college, and technical-vocational programs. Its tertiary offerings include Computer Science, Information Technology, Business Administration, Accountancy, Accounting Information System, Hospitality Management, Multimedia Arts, Communication, and Tourism Management. The campus is located along N. Guevarra Street in Dasmariñas','[{\"title\":\"Entrance Exam\",\"desc\":\"Verify testing requirements with the admissions office.\",\"status\":\"Verify\"},{\"title\":\"Birth Certificate\",\"desc\":\"Original and photocopy of Birth Certificate.\",\"status\":\"Required\"},{\"title\":\"Report Card\",\"desc\":\"Form 138 \\/ Grade 12 Report Card.\",\"status\":\"Required\"},{\"title\":\"Permanent Record\",\"desc\":\"Form 137 \\/ SF10 from previous school.\",\"status\":\"Required\"},{\"title\":\"Good Moral Certificate\",\"desc\":\"Certificate of good moral character.\",\"status\":\"Required\"},{\"title\":\"Pictures\",\"desc\":\"Recent formal ID pictures.\",\"status\":\"Required\"}]',0),(7,'FEAPITSAT','FEAPITSAT','Private','school-profile?id=FEAPITSAT',NULL,'/riasec/assets/colleges/image7.jpeg','Dasmariñas City, Cavite',NULL,NULL,'FEAPITSAT, Dasmariñas, Cavite','FEAPITSAT College of Dasmariñas is an educational and technical-vocational institution established to provide academic and skills-based education to students in Cavite. It began accepting applicants in Dasmariñas during School Year 2012–2013. The institution has offered TESDA-recognized competency programs including Bartending, Food and Beverage Services, Bookkeeping, Visual Graphics Design, and Event Management Services','[{\"title\":\"Entrance Exam\",\"desc\":\"Please verify specific testing schedules with the admissions office.\",\"status\":\"Verify\"},{\"title\":\"Birth Certificate\",\"desc\":\"PSA or NSO authenticated copy.\",\"status\":\"Required\"},{\"title\":\"Form 138\\/Report Card\",\"desc\":\"Original copy of high school report card.\",\"status\":\"Required\"},{\"title\":\"Good Moral Certificate\",\"desc\":\"Certificate of good moral character.\",\"status\":\"Required\"}]',0),(8,'PHINMA St. Jude College Dasmariñas','PHINMA','Private','school-profile?id=PHINMA',NULL,'/riasec/assets/colleges/image8.jpeg','Dasmariñas City, Cavite',NULL,NULL,'PHINMA St. Jude College Dasmariñas, Dasmariñas, Cavite','PHINMA Saint Jude College–Dasmariñas is a private, non-sectarian institution located in Salitran IV, Dasmariñas. It became part of the PHINMA Education network in 2024. The school aims to provide accessible and quality education and offers programs including Nursing, Radiologic Technology, Psychology, Hospitality Management, Computer Science, and other academic programs.','[{\"title\":\"Form 138 with LRN\",\"desc\":\"Grade 12 Report Card containing Learner Reference Number.\",\"status\":\"Required\"},{\"title\":\"PSA Birth Certificate\",\"desc\":\"Original PSA-authenticated copy.\",\"status\":\"Required\"},{\"title\":\"2x2 Pictures\",\"desc\":\"Recent 2x2 ID pictures.\",\"status\":\"Required\"},{\"title\":\"Long Brown Envelope\",\"desc\":\"For compiling documentary requirements.\",\"status\":\"Required\"}]',0),(9,'STI College','STI','Private','school-profile?id=STI',NULL,'/riasec/assets/colleges/image9.jpeg','Dasmariñas City, Cavite',NULL,NULL,'STI College, Dasmariñas, Cavite','STI College–Dasmariñas is a private educational institution offering senior high school, college, and technical-vocational programs. Its tertiary offerings include Computer Science, Information Technology, Business Administration, Accountancy, Accounting Information System, Hospitality Management, Multimedia Arts, Communication, and Tourism Management. The campus is located along N. Guevarra Street in Dasmariñas','[{\"title\":\"Form 138\\/SF9\",\"desc\":\"Grade 12 Report Card.\",\"status\":\"Required\"},{\"title\":\"Form 137\\/SF10\",\"desc\":\"Student Permanent Record.\",\"status\":\"Required\"},{\"title\":\"PSA Birth Certificate\",\"desc\":\"Original PSA-authenticated copy.\",\"status\":\"Required\"},{\"title\":\"Good Moral Certificate\",\"desc\":\"Certificate of good moral character.\",\"status\":\"Required\"},{\"title\":\"Medical Cert & X-ray\",\"desc\":\"Medical clearance and chest X-ray results.\",\"status\":\"Required\"},{\"title\":\"Health Screening\",\"desc\":\"Additional health screening where applicable.\",\"status\":\"Required\"}]',0),(10,'Kolehiyo ng Lungsod ng Dasmariñas','KLD','Public','school-profile?id=KLD',NULL,'/riasec/assets/colleges/image10.jpeg','Dasmariñas City, Cavite',NULL,NULL,'Kolehiyo ng Lungsod ng Dasmariñas, Dasmariñas, Cavite','Kolehiyo ng Lungsod ng Dasmariñas is a city-established higher education institution created to provide quality and equitable tertiary education to qualified Dasmarineños. It was formally established through a city ordinance in 2021 and focuses on developing knowledgeable, capable, and socially responsible graduates. Its programs include Psychology, Information Systems, Nursing, Civil Engineering, Life Sciences, Computer Science, Social Work, and Midwifery.','[{\"title\":\"KLD Admission Test\",\"desc\":\"Required entrance examination for all applicants.\",\"status\":\"Required\"},{\"title\":\"Academic Records\\/Grades\",\"desc\":\"Form 138 showing minimum GPA requirements.\",\"status\":\"Required\"},{\"title\":\"Valid ID\",\"desc\":\"Student ID or any government-issued valid ID.\",\"status\":\"Required\"},{\"title\":\"Enrollment Form\",\"desc\":\"Accomplished KLD enrollment application form.\",\"status\":\"Required\"},{\"title\":\"Interview\",\"desc\":\"Department interview, if applicable for the program.\",\"status\":\"Verify\"},{\"title\":\"Minimum GPA\",\"desc\":\"Must meet the college minimum GPA requirements.\",\"status\":\"Required\"}]',0),(11,'National University','NU','Private','school-profile?id=NU',NULL,'/riasec/assets/colleges/image11.jpeg','Dasmariñas City, Cavite',NULL,NULL,'National University, Dasmariñas, Cavite','National University–Dasmariñas is a campus of National University established in 2021. It provides accessible and quality education for students in Cavite and Southern Luzon, with programs in areas such as engineering, business, accountancy, information technology, psychology, hospitality management, architecture, and education. The campus emphasizes preparing students to become future-ready professionals.','[{\"title\":\"NU Quest Application\",\"desc\":\"Online application through the NU Quest portal.\",\"status\":\"Required\"},{\"title\":\"Academic Records\",\"desc\":\"Original high school report card or transcript.\",\"status\":\"Required\"}]',0),(12,'PNTC Colleges','PNTC','Private','school-profile?id=PNTC',NULL,'/riasec/assets/colleges/image12.jpeg','Dasmariñas City, Cavite',NULL,NULL,'PNTC Colleges, Dasmariñas, Cavite','PNTC Colleges is a private, non-sectarian maritime and business school based in Dasmariñas. Founded in 1994 as the Philippine Nautical Training Institute, it developed into PNTC Colleges and expanded its offerings beyond maritime education. The institution provides higher education, maritime training, and competency assessment, with a strong focus on producing competent and globally competitive maritime professionals.','[{\"title\":\"PNTC Admission Test\",\"desc\":\"Required for incoming freshmen.\",\"status\":\"Required\"},{\"title\":\"Notification Letter\",\"desc\":\"Admission notice from the university.\",\"status\":\"Required\"},{\"title\":\"Medical Waiver\",\"desc\":\"Signed medical waiver form.\",\"status\":\"Required\"},{\"title\":\"Vaccination Card\",\"desc\":\"Proof of vaccination.\",\"status\":\"Required\"},{\"title\":\"Parent\'s ID\",\"desc\":\"Photocopy of parent or guardian\'s valid ID.\",\"status\":\"Required\"},{\"title\":\"Good Moral Certificate\",\"desc\":\"Certificate of good moral character.\",\"status\":\"Required\"},{\"title\":\"PSA Birth Certificate\",\"desc\":\"Original PSA-authenticated copy.\",\"status\":\"Required\"},{\"title\":\"1x1 & 2x2 Pictures\",\"desc\":\"Recent colored ID pictures.\",\"status\":\"Required\"},{\"title\":\"Form 138\\/SF9\",\"desc\":\"Senior High School Report Card.\",\"status\":\"Required\"},{\"title\":\"Medical Examination\",\"desc\":\"Physical and medical clearance.\",\"status\":\"Required\"},{\"title\":\"Ishihara Test\",\"desc\":\"Color blindness test, required for maritime programs.\",\"status\":\"Required\"}]',0),(14,'asdsadsa','sda','Private','school-profile?id=sda',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,1);
